def intervals_overlap(a_start, a_end, b_start, b_end):
    # half-open intervals [start, end); True iff they share at least one point
    return a_start < b_end and b_start < a_end

from overlap import intervals_overlap


def test_overlapping():
    assert intervals_overlap(0, 10, 5, 15)


def test_disjoint():
    assert not intervals_overlap(0, 2, 50, 60)


def test_touching_b_starts_at_a_end():
    # half-open: [0,5) and [5,9) share no point
    assert not intervals_overlap(0, 5, 5, 9)


def test_touching_a_starts_at_b_end():
    # symmetric orientation: [5,10) and [0,5) share no point
    assert not intervals_overlap(5, 10, 0, 5)


def test_containment():
    assert intervals_overlap(0, 10, 3, 5)
    assert intervals_overlap(3, 5, 0, 10)


def test_symmetry_reversed_arguments():
    assert intervals_overlap(5, 15, 0, 10)
    assert not intervals_overlap(50, 60, 0, 2)

